    Counterparty = apps.get_model("parties", "Counterparty")
    for field in ("linked_user_id", "linked_company_id"):
        groups = {}
        for model, role in ((Client, None), (Counterparty, "")):
            for card in model.objects.exclude(**{field: None}).exclude(state="merged"):
                key = (card.company_id, getattr(card, field))
                groups.setdefault(key, []).append((role if role is None else card.role, card))
        for (company_id, _profile), cards in groups.items():
            roles = [r for r, _ in cards]
            kinds = {c.kind for _, c in cards}
            if len(cards) < 2 or len(set(roles)) != len(roles) or len(kinds) != 1:
                continue
            if any(c.party_id is not None for _, c in cards):
                continue
            party = Party.objects.create(company_id=company_id)
            for _, card in cards:
                card.party_id = party.id
                card.save(update_fields=["party"])


